gaUN(){return"\uce21\uba74\uc5d0\uc11c \uc804\uc2e0\uacfc \uc591\ubc1c\uc774 \uc548\ub0b4\uc120 \uc548\uc5d0 \ubcf4\uc774\uac8c \ucd2c\uc601\ud558\uc138\uc694."},
gaV9(){return"\ucd2c\uc601 \uc2dc\uc791"},
